package com.ianblk.zianmobs;
import java.nio.file.*;
import java.util.*;
import net.minecraft.client.*;
import net.minecraft.server.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.*;
import net.minecraft.world.level.GameType;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import net.neoforged.neoforge.event.tick.ServerTickEvent;
/** Opt-in live flight observation confined to the disposable scene world. */
public final class CompanionFlightSceneClient {
 private static final List<String> IDS=List.of("otter","kit","clank","cubee_fire","cubee_swag_pillager");
 private static MinecraftServer server;private static ServerPlayer owner;private static CompanionEntity pet;private static int boot,index=-1,start;private static boolean dispatched;private static volatile Throwable failure;private static volatile String ready="";private static String captured="";private static int shots;private static int armorPose=-1,armorTicks;
 public static void register(){if(Boolean.getBoolean("zianmobs.flightScene")){NeoForge.EVENT_BUS.addListener(CompanionFlightSceneClient::client);NeoForge.EVENT_BUS.addListener(CompanionFlightSceneClient::tick);}}
 private static void next(){if(pet!=null)Companions.current.store(owner.getUUID(),false);if(++index>=IDS.size()){ready="done";return;}String id=IDS.get(index);Companions.current.grant(owner.getUUID(),id,Long.MAX_VALUE);Companions.current.summon(owner,id);pet=Companions.current.activeEntity(owner.getUUID());start=server.getTickCount();ready="";}
 private static void setup(MinecraftServer s){if(!s.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).toAbsolutePath().toString().contains("mobs-scene-client"))throw new IllegalStateException("Flight scene outside isolated world");server=s;CompanionScene.setup(s);owner=s.getPlayerList().getPlayers().getFirst();var level=s.overworld();double floor=level.getHeight(net.minecraft.world.level.levelgen.Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,52,39);for(var entity:level.getEntitiesOfClass(LivingEntity.class,new net.minecraft.world.phys.AABB(33,floor-8,28,99,floor+12,70)))if(entity instanceof CompanionEntity||entity instanceof Snowbone)entity.discard();owner.setGameMode(GameType.SURVIVAL);owner.setHealth(owner.getMaxHealth());owner.removeAllEffects();owner.teleportTo(level,52,floor,39,0,8);next();}
 private static void tick(ServerTickEvent.Post event){if(server==null||event.getServer()!=server||failure!=null||index>=IDS.size())return;try{if(server.getTickCount()-start>=60){if(pet==null||!pet.isAlive()||pet.getY()-owner.getY()<.35||!pet.isNoGravity()||!owner.level().noCollision(pet))throw new IllegalStateException("Live companion failed to hover: "+IDS.get(index));ready=IDS.get(index);}if(server.getTickCount()-start>=85)next();}catch(Throwable ex){failure=ex;}}
 private static void client(ClientTickEvent.Post event){var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;mc.options.pauseOnLostFocus=false;if(mc.screen instanceof net.minecraft.client.gui.screens.TitleScreen&&++boot==35){mc.createWorldOpenFlows().openWorld("companions-scene",()->mc.stop());return;}if(armorPose>=0){try{if(++armorTicks>=45){armorTicks=0;Screenshot.grab(mc.gameDirectory,"thanos-fit-"+armorPose+".png",mc.getMainRenderTarget(),c->{});if(++armorPose<3)mc.setScreen(new com.ianblk.zianmobs.client.TitanArmorPreviewScreen(armorPose));else{Files.writeString(mc.gameDirectory.toPath().resolve("armor-fit-result.txt"),"PASS: native wide and slim armor rendering, original UVs, standing/crouching/bow poses, preserved model visibility and repeated slim/wide alternation.\n");mc.stop();}}}catch(Throwable ex){ZianMobs.LOGGER.error("ARMOR-FIT FAIL",ex);try{Files.writeString(mc.gameDirectory.toPath().resolve("armor-fit-result.txt"),"FAIL: "+ex);}catch(Exception ignored){}mc.stop();}return;}if(mc.screen!=null||mc.level==null||mc.player==null||mc.getSingleplayerServer()==null)return;try{if(failure!=null)throw new IllegalStateException("Live flight failed",failure);mc.options.hideGui=true;mc.options.setCameraType(CameraType.THIRD_PERSON_BACK);mc.options.fov().set(65);if(!dispatched){dispatched=true;mc.getSingleplayerServer().execute(()->{try{setup(mc.getSingleplayerServer());}catch(Throwable ex){failure=ex;}});return;}if(!ready.isEmpty()&&!ready.equals("done")&&!ready.equals(captured)){captured=ready;Screenshot.grab(mc.gameDirectory,"flight-"+ready+".png",mc.getMainRenderTarget(),c->{});shots++;}if(ready.equals("done")){if(shots!=IDS.size())throw new IllegalStateException("Missing live flight captures");Files.writeString(mc.gameDirectory.toPath().resolve("flight-scene-result.txt"),"PASS: five owned previously terrestrial companions visibly hover with native AI and normal client/server synchronization.\n");armorPose=0;mc.setScreen(new com.ianblk.zianmobs.client.TitanArmorPreviewScreen(0));}}catch(Throwable ex){ZianMobs.LOGGER.error("FLIGHT-SCENE FAIL",ex);try{Files.writeString(mc.gameDirectory.toPath().resolve("flight-scene-result.txt"),"FAIL: "+ex);}catch(Exception ignored){}mc.stop();}}
}
